BEGIN;
DO $$ BEGIN IF current_database()<>'athyper_studio' OR current_setting('app.database_plane',true)<>'studio' THEN RAISE EXCEPTION 'Entity surface component binding requires the Studio plane'; END IF; END $$;

CREATE TABLE metadata.entity_surface_component_binding (
 id uuid NOT NULL DEFAULT shared.uuidv7(),tenant_id uuid,entity_id uuid NOT NULL,change_set_id uuid NOT NULL,entity_surface_id uuid NOT NULL,entity_surface_section_id uuid,component_surface_id uuid NOT NULL,
 binding_key text NOT NULL,position smallint NOT NULL,cardinality text NOT NULL,contract_slice_pointer text NOT NULL,status metadata.entity_member_status_d NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz,updated_by uuid,
 CONSTRAINT entity_surface_component_binding_pkey PRIMARY KEY(id),CONSTRAINT entity_surface_component_binding_tenant_uq UNIQUE NULLS NOT DISTINCT(tenant_id,id),CONSTRAINT entity_surface_component_binding_key_uq UNIQUE NULLS NOT DISTINCT(tenant_id,entity_surface_id,binding_key),CONSTRAINT entity_surface_component_binding_position_uq UNIQUE NULLS NOT DISTINCT(tenant_id,entity_surface_id,entity_surface_section_id,position),
 CONSTRAINT entity_surface_component_binding_key_chk CHECK(binding_key ~ '^[a-z][a-z0-9_.-]{1,126}$'),CONSTRAINT entity_surface_component_binding_position_chk CHECK(position>=0),CONSTRAINT entity_surface_component_binding_cardinality_chk CHECK(cardinality IN('one','many')),CONSTRAINT entity_surface_component_binding_pointer_chk CHECK(contract_slice_pointer ~ '^/(?:[^/~]|~[01])+(?:/(?:[^/~]|~[01])+)*$' AND length(contract_slice_pointer)<=512),CONSTRAINT entity_surface_component_binding_no_self_chk CHECK(component_surface_id<>entity_surface_id),CONSTRAINT entity_surface_component_binding_audit_chk CHECK((updated_at IS NULL)=(updated_by IS NULL)),
 CONSTRAINT entity_surface_component_binding_entity_fk FOREIGN KEY(entity_id) REFERENCES metadata.entity(id) ON DELETE RESTRICT,CONSTRAINT entity_surface_component_binding_change_set_fk FOREIGN KEY(change_set_id) REFERENCES metadata.entity_change_set(id) ON DELETE CASCADE,CONSTRAINT entity_surface_component_binding_surface_fk FOREIGN KEY(entity_surface_id) REFERENCES metadata.entity_surface(id) ON DELETE CASCADE,CONSTRAINT entity_surface_component_binding_section_fk FOREIGN KEY(entity_surface_section_id) REFERENCES metadata.entity_surface_section(id) ON DELETE CASCADE,CONSTRAINT entity_surface_component_binding_component_fk FOREIGN KEY(component_surface_id) REFERENCES metadata.entity_surface(id) ON DELETE RESTRICT,CONSTRAINT entity_surface_component_binding_created_by_fk FOREIGN KEY(created_by) REFERENCES master.principal(id) ON DELETE RESTRICT,CONSTRAINT entity_surface_component_binding_updated_by_fk FOREIGN KEY(updated_by) REFERENCES master.principal(id) ON DELETE RESTRICT
);
CREATE INDEX ix_entity_surface_component_binding_component ON metadata.entity_surface_component_binding(tenant_id,component_surface_id,entity_surface_id);
ALTER TABLE metadata.entity_surface_component_binding ENABLE ROW LEVEL SECURITY;
ALTER TABLE metadata.entity_surface_component_binding FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_read ON metadata.entity_surface_component_binding FOR SELECT TO athyperapp USING(tenant_id IS NULL OR tenant_id=shared.current_tenant_id_soft());
CREATE POLICY tenant_insert ON metadata.entity_surface_component_binding FOR INSERT TO athyperapp WITH CHECK(tenant_id=shared.current_tenant_id() AND created_by=master.current_principal_id_soft());
CREATE POLICY tenant_update ON metadata.entity_surface_component_binding FOR UPDATE TO athyperapp USING(tenant_id=shared.current_tenant_id_soft()) WITH CHECK(tenant_id=shared.current_tenant_id());
CREATE POLICY tenant_delete ON metadata.entity_surface_component_binding FOR DELETE TO athyperapp USING(tenant_id=shared.current_tenant_id_soft());
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='athyperadmin') THEN CREATE POLICY admin_access ON metadata.entity_surface_component_binding FOR ALL TO athyperadmin USING(true) WITH CHECK(true); END IF; END $$;
REVOKE ALL ON metadata.entity_surface_component_binding FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON metadata.entity_surface_component_binding TO athyperapp;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='athyperadmin') THEN GRANT ALL PRIVILEGES ON metadata.entity_surface_component_binding TO athyperadmin; END IF; END $$;
COMMIT;
